import pytest
from solution import string_xor

def test_xor_basic_example():
    assert string_xor('010', '110') == '100'

def test_xor_all_zeros():
    assert string_xor('000', '000') == '000'

def test_xor_all_ones():
    assert string_xor('111', '111') == '000'

def test_xor_different_lengths_even_logic():
    # Note: Standard XOR logic usually implies equal length, 
    # but based on the docstring, we assume standard bitwise behavior.
    # If lengths differ, behavior depends on implementation, 
    # but here we test standard equal length.
    assert string_xor('1010', '0101') == '1111'

def test_xor_single_bit_zero():
    assert string_xor('0', '0') == '0'

def test_xor_single_bit_one():
    assert string_xor('1', '1') == '0'

def test_xor_mixed_bits():
    assert string_xor('1100', '1010') == '0110'

def test_xor_long_string():
    assert string_xor('11111111', '00000000') == '11111111'

def test_xor_alternating_bits():
    assert string_xor('101010', '101010') == '000000'

def test_xor_identity():
    assert string_xor('1101', '0000') == '1101'
